import random

def count_overlaps(A, B):
    count = 0
    for i in A:
        for j in B:
            if max(i[0], j[0]) <= min(i[1], j[1]):
                count += 1
    return count

def is_valid(S, K):
    # Check if at any point, the number of intervals is <= K
    events = []
    for start, end in S:
        events.append((start, 1))
        events.append((end, -1))
    events.sort()

    curr = 0
    for _, type in events:
        curr += type
        if curr > K:
            return False
    return True

def random_intervals(N, K):
    # This is a very naive way to generate intervals.
    # A better way would be to create K layers of disjoint intervals.
    S = []
    for k in range(K):
        # Create N // K disjoint intervals in this layer
        num_int = N // K
        # Simple partition of [0, 1]
        for i in range(num_int):
            S.append((i / num_int, (i + 1) / num_int))

    # If N is not divisible by K, add remaining
    while len(S) < N:
        S.append((random.random(), random.random())) # This might violate K
        if not is_valid(S, K):
            S.pop()

    # To make it more random, we can shuffle and perturb
    return S

def solve_small(N, K):
    max_n = 0
    for _ in range(1000):
        # Generate A and B as K layers of N/K disjoint intervals
        def generate_K_layers(N, K):
            S = []
            for k in range(K):
                # Randomly partition [0, 1] into N//K intervals
                points = sorted([random.random() for _ in range(N // K - 1)])
                points = [0] + points + [1]
                for i in range(len(points) - 1):
                    S.append((points[i], points[i+1]))
            # Handle N % K
            while len(S) < N:
                start = random.random()
                end = random.random()
                if start > end: start, end = end, start
                S.append((start, end))
                if not is_valid(S, K):
                    S.pop()
            return S

        A = generate_K_layers(N, K)
        B = generate_K_layers(N, K)
        max_n = max(max_n, count_overlaps(A, B))
    return max_n

